from gen import *
IN='#12151A'; IN2='#0B0D10'; CARD='#181C22'; BD='#2C3138'; MUT='#A3A9B1'; DIM='#7D848D'
def sec(inner,bg=IN,pad='30px 20px',al='center'): return row(inner,f'padding:{pad};text-align:{al};background:{bg};')
def wbtn(t,w='100%',bg='#FFFFFF',fg='#0D0F12'): return btn(t,bg,fg,w,12,'15px 12px',15)
def H(a,b,sub='',acc='#8E959E',size=26): return f'<div style="font-size:{size}px;line-height:1.15;font-weight:800;color:#FFF;">{a}<br><span style="color:{acc};">{b}</span></div>'+(f'<div style="font-size:14px;line-height:1.6;color:{MUT};margin:10px auto 0;max-width:430px;">{sub}</div>' if sub else '')
def foot(bg=IN): return row(f'<div style="height:1px;background:{BD};margin:0 0 26px;"></div>'+logo(True,54)+f'<div style="font-size:11px;color:{DIM};margin-top:14px;line-height:1.6;">{LAB}</div>'+unsub(DIM),f'padding:0 22px 32px;text-align:center;background:{bg};')
def hero(img,bg=IN): return row(f'<img src="{U}sp-email/{img}" width="600" style="display:block;width:100%;height:auto;border:0;">',f'padding:0;line-height:0;background:{bg};')
def lastrows(bd=BD):
    return ''.join(f'<tr><td width="70" style="padding:9px 0;border-bottom:1px solid {bd};"><img src="{P[k][3]}" width="58" height="58" style="display:block;border-radius:12px;"></td><td style="padding:9px 4px;border-bottom:1px solid {bd};text-align:left;font-family:{F};"><div style="font-size:15px;font-weight:800;color:#FFF;">{n}</div><div style="font-size:12px;color:{MUT};">{m}</div></td></tr>' for k,n,m in LAST)
def listprod(keys,arrow='→',acc='#FFFFFF'):
    r=''.join(f'<tr><td style="padding:5px 0;"><a href="#" style="display:block;text-decoration:none;background:{CARD};border:1px solid {BD};border-radius:16px;overflow:hidden;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td width="96" style="width:96px;line-height:0;"><img src="{P[k][3]}" width="96" height="96" style="display:block;width:96px;height:96px;border:0;"></td><td style="padding:10px 14px;text-align:left;font-family:{F};"><div style="font-size:16px;font-weight:800;color:#FFF;">{P[k][0]}</div><div style="font-size:12px;color:{MUT};margin-top:2px;">{P[k][1]}</div><div style="font-size:13px;font-weight:700;color:#D9DDE2;margin-top:6px;">{P[k][2]}</div></td><td width="40" style="font-size:20px;color:{acc};font-family:{F};text-align:center;">{arrow}</td></tr></table></a></td></tr>' for k in keys)
    return f'<table role="presentation" width="100%" cellpadding="0" cellspacing="0">{r}</table>'
def tiles():
    c=[f'<div style="background:{CARD};border:1px solid {BD};border-radius:14px;padding:16px 8px;text-align:center;"><div style="font-size:22px;">{i}</div><div style="font-size:13px;font-weight:800;color:#FFF;margin-top:6px;">{a}</div><div style="font-size:11px;color:{MUT};margin-top:2px;">{b}</div></div>' for i,a,b in TRUST]
    return grid(c)
def steps(acc='#FFFFFF',fg='#0D0F12'):
    st=[('Code kopieren','unten in der Mail'),('Produkte wählen','im Shop'),('An der Kasse einfügen','10 % sofort weg')]
    r=''.join(f'<tr><td width="46" valign="top" style="padding:8px 0;"><div style="width:34px;height:34px;line-height:34px;border-radius:50%;background:{acc};color:{fg};font-weight:800;font-size:15px;text-align:center;font-family:{F};">{n+1}</div></td><td style="padding:8px 0;text-align:left;font-family:{F};"><div style="font-size:15px;font-weight:800;color:#FFF;">{a}</div><div style="font-size:12px;color:{MUT};">{b}</div></td></tr>' for n,(a,b) in enumerate(st))
    return f'<table role="presentation" width="100%" cellpadding="0" cellspacing="0">{r}</table>'
def codecard(acc='#D9DDE2',border=BD,cta=None,ctabg='#FFFFFF',ctafg='#0D0F12'):
    return f'<div style="border:1px solid {border};background:{CARD};border-radius:18px;padding:22px 14px;"><div style="font-size:52px;font-weight:800;color:#FFF;line-height:1;">10 %</div><div style="font-size:11px;font-weight:700;letter-spacing:.18em;color:{MUT};margin:10px 0 14px;">AUF DEINE ERSTE BESTELLUNG</div><div style="border:1.5px dashed #59606A;border-radius:12px;padding:12px;font-size:24px;font-weight:800;font-family:{MONO};color:{acc};letter-spacing:.04em;">{CODE}</div><div style="font-size:12px;color:{DIM};margin-top:10px;">gültig bis 14.11.2026 · einmal einlösbar</div></div>'+('<div style="height:16px;"></div>'+wbtn(cta,'100%',ctabg,ctafg) if cta else '')
M={}
# ---- B2: Bild zuerst, Produkte als Liste ----
def b2top(eb,a,b,sub,img): return hero(img,IN2)+row(f'<div style="margin-bottom:16px;">{logo(True,36,False)}</div><div style="font-size:11px;font-weight:700;letter-spacing:.2em;color:{MUT};">{eb}</div><div style="font-size:32px;line-height:1.1;font-weight:800;color:#FFF;margin:10px 0 10px;">{a}<br><span style="color:#8E959E;">{b}</span></div><div style="font-size:15px;line-height:1.5;color:{MUT};">{sub}</div>',f'padding:0 20px 26px;text-align:center;background:{IN2};margin-top:-30px;')
M['B2-willkommen']=T(b2top('DEIN WILLKOMMENSGESCHENK','Willkommen.','10 % für dich.','Dein persönlicher Code für die erste Bestellung:','nl-hero-vials.jpg')+sec(codecard(cta='Jetzt einlösen'),IN2,'0 20px 30px')+sec(H('Beliebt bei','Insidern.')+'<div style="height:16px;"></div>'+listprod(['reta','ghk','pen','mots']))+sec(tiles(),IN2,'24px 15px')+foot(IN2),IN2,IN2)
M['B2-nachkauf']=T(b2top('NACHBESTELLEN','Zeit für','Nachschub?','Deine letzte Bestellung ist rund 4 Wochen her.','nl-hero-pen.jpg')+sec(f'<div style="background:{CARD};border:1px solid {BD};border-radius:16px;padding:6px 14px 14px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-bottom:14px;">{lastrows()}</table>'+wbtn('Gleiche Bestellung nochmal')+'</div>',IN2,'0 20px 30px')+sec(H('Das könnte auch','passen.')+'<div style="height:16px;"></div>'+listprod(['ghk','mots','pen']))+sec(tiles(),IN2,'24px 15px')+foot(IN2),IN2,IN2)
# ---- B3: B + Orange-Buttons, Ticket ----
OR='#FF6B35'
def obtn(t,w='100%'): return btn(t,OR,'#FFF',w,12,'15px 12px',15)
def b3top(a,b,sub,cta,img): return row(logo(True,44)+f'<div style="font-size:32px;line-height:1.1;font-weight:800;color:#FFF;margin:20px 0 10px;">{a}<br><span style="color:#8E959E;">{b}</span></div><div style="font-size:15px;line-height:1.5;color:{MUT};margin-bottom:22px;">{sub}</div>'+obtn(cta,'86%'),f'padding:30px 20px 24px;text-align:center;background:{IN};')+hero(img)
def ticket(): return f'<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:separate;border-radius:16px;overflow:hidden;border:1px solid {BD};"><tr><td width="36%" style="background-color:#2A2F36;background-image:linear-gradient(135deg,#3A4048,#1A1E23);padding:20px 6px;text-align:center;font-family:{F};border-right:2px dashed {IN};"><div style="font-size:32px;font-weight:800;color:#FFF;line-height:1;">10 %</div><div style="font-size:10px;font-weight:700;letter-spacing:.14em;color:{MUT};margin-top:6px;">WILLKOMMEN</div></td><td style="background:{CARD};padding:16px 10px;text-align:center;font-family:{F};"><div style="font-size:10px;font-weight:700;letter-spacing:.14em;color:{MUT};">DEIN CODE</div><div style="font-size:21px;font-weight:800;font-family:{MONO};color:#FFF;margin:6px 0 3px;">{CODE}</div><div style="font-size:11px;color:{DIM};">gültig bis 14.11.2026</div></td></tr></table>'
def gridprod(keys):
    c=[f'<div style="background:{CARD};border:1px solid {BD};border-radius:14px;overflow:hidden;text-align:center;"><img src="{P[k][3]}" width="150" style="display:block;width:100%;height:auto;border:0;"><div style="padding:10px 8px 12px;"><div style="font-size:14px;font-weight:800;color:#FFF;">{P[k][0]}</div><div style="font-size:12px;color:{MUT};margin:2px 0 10px;">{P[k][2]}</div>{btn("Ansehen",OR,"#FFF",r=8,pad="8px 6px",fs=12)}</div></div>' for k in keys]
    return grid(c)
M['B3-willkommen']=T(b3top('Willkommen bei','Peptrium.','Schön, dass du dabei bist. Dein Geschenk wartet unten.','Zum Shop','nl-hero-vials.jpg')+sec(H('Dein Willkommens-','geschenk.')+'<div style="height:16px;"></div>'+ticket()+'<div style="height:16px;"></div>'+obtn('Code jetzt einlösen'))+sec(H('So einfach','geht’s.')+'<div style="height:12px;"></div>'+steps(OR,'#FFF'),IN,'10px 24px 26px')+sec(H('Beliebt bei','Insidern.')+'<div style="height:16px;"></div>'+gridprod(['reta','ghk','pen','mots']),IN,'26px 15px')+foot(),IN2,IN)
M['B3-nachkauf']=T(b3top('Zeit für','Nachschub?','Deine letzte Bestellung ist rund 4 Wochen her.','Jetzt nachbestellen','nl-hero-pen.jpg')+sec(H('Deine letzte','Bestellung.','Mit einem Klick wieder im Warenkorb.')+f'<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:14px 0 18px;">{lastrows()}</table>'+obtn('Gleiche Bestellung nochmal'))+sec(H('Unser Standard.','Wie immer.')+'<div style="height:16px;"></div>'+tiles(),IN,'26px 15px')+sec(H('Das könnte auch','passen.')+'<div style="height:16px;"></div>'+gridprod(['ghk','mots']),IN,'26px 15px')+foot(),IN2,IN)
# ---- B4: Editorial, wechselnde Flächen, Chrom-Rahmen ----
CHR='background-color:#2A2F36;background-image:linear-gradient(135deg,#F2F4F6 0%,#8E959E 35%,#3A4048 60%,#C9CED6 100%);'
def chromebox(inner): return f'<div style="{CHR}border-radius:20px;padding:1.5px;"><div style="background:{CARD};border-radius:19px;padding:24px 16px;">{inner}</div></div>'
def b4top(eb,a,sub,img): return row(f'<table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td style="text-align:left;"><img src="{LOGO}" width="30" height="30" style="display:inline-block;vertical-align:middle;"><span style="display:inline-block;vertical-align:middle;margin-left:8px;font-size:12px;font-weight:800;letter-spacing:.3em;color:#E6E8EB;font-family:{F};">PEPTRIUM</span></td><td style="text-align:right;font-size:11px;color:{DIM};font-family:{F};">{eb}</td></tr></table>',f'padding:16px 20px;background:{IN2};border-bottom:1px solid {BD};')+row(f'<div style="font-size:38px;line-height:1.05;font-weight:800;color:#FFF;letter-spacing:-.02em;">{a}</div><div style="font-size:15px;line-height:1.55;color:{MUT};margin-top:12px;">{sub}</div>',f'padding:30px 22px 26px;text-align:left;background:{IN2};')+hero(img,IN2)
def num(n,t): return f'<div style="font-size:12px;font-weight:700;letter-spacing:.2em;color:{DIM};margin-bottom:8px;">{n} — {t}</div>'
def h4(t): return f'<div style="font-size:24px;line-height:1.2;font-weight:800;color:#FFF;margin-bottom:16px;">{t}</div>'
M['B4-willkommen']=T(b4top('Willkommen','Schön, dass<br>du da bist.','Als Dankeschön bekommst du 10 % auf deine erste Bestellung.','nl-hero-vials.jpg')+sec(num('01','Dein Geschenk')+chromebox(f'<div style="text-align:center;"><div style="font-size:52px;font-weight:800;color:#FFF;line-height:1;">10 %</div><div style="font-size:24px;font-weight:800;font-family:{MONO};color:#D9DDE2;letter-spacing:.04em;margin:14px 0 6px;">{CODE}</div><div style="font-size:12px;color:{DIM};">gültig bis 14.11.2026</div></div>')+'<div style="height:16px;"></div>'+wbtn('Code jetzt einlösen'),IN,'30px 20px','left')+sec(num('02','So geht’s')+steps(),IN2,'28px 22px','left')+sec(num('03','Beliebt')+listprod(['reta','ghk','pen']),IN,'28px 20px','left')+sec(num('04','Unser Standard')+tiles(),IN2,'28px 15px','left')+foot(IN2),IN2,IN2)
M['B4-nachkauf']=T(b4top('Nachbestellen','Zeit für<br>Nachschub?','Deine letzte Bestellung ist rund 4 Wochen her. Mit einem Klick ist alles wieder im Warenkorb.','nl-hero-pen.jpg')+sec(num('01','Deine letzte Bestellung')+chromebox(f'<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-bottom:16px;">{lastrows()}</table>'+wbtn('Gleiche Bestellung nochmal')),IN,'30px 20px','left')+sec(num('02','Passt dazu')+listprod(['ghk','mots']),IN2,'28px 20px','left')+sec(num('03','Unser Standard')+tiles(),IN,'28px 15px','left')+foot(),IN2,IN2)
for k,v in M.items(): open(k+'.html','w').write(v)
print(list(M))
